        r=e['result']; print('VERDICT:', r['verdict'], dict(Counter(i['severity'] for i in r['issues'])))
        print('RAN tail:', r['what_i_ran'][-1300:])
        for i in r['issues']: print('  [%s] %s'%(i['severity'], i['description'][:300]))
"; systemctl --user list-units 'telelean-*' --no-legend | wc -l; wc -l < ~/.elan/known-projects

